<?php use Hls\Http\View as V; ?>
<?php if($access->can('finance.payable.create')): ?><section class="panel"><form method="post" class="form-grid"><?= $this->csrf() ?><label>Supplier<select name="supplier_id" required><?php foreach($suppliers as $s): ?><option value="<?= (int)$s['id'] ?>"><?= V::escape($s['name']) ?></option><?php endforeach ?></select></label><label>Cabang<select name="branch_id" required><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>"><?= V::escape($b['code'].' - '.$b['name']) ?></option><?php endif; endforeach ?></select></label><label>Nomor tagihan<input name="bill_ref" required></label><label>Tanggal<input type="date" name="bill_date" value="<?= date('Y-m-d') ?>" required></label><label>Jatuh tempo<input type="date" name="due_date"></label><div data-bill-items><div class="bill-item"><input name="description[]" placeholder="Deskripsi" required><input name="quantity[]" type="number" min="0.001" step="0.001" placeholder="Kuantitas" required><input name="unit_price[]" type="number" min="0" step="0.01" placeholder="Harga" required><button type="button" data-remove-item>Hapus Item</button></div></div><button type="button" data-add-item>+ Tambah Item</button><button class="button button-primary">Simpan Draft</button></form></section><?php endif ?><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Tagihan</th><th>Supplier</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= V::escape($r['bill_ref']) ?></td><td><?= V::escape($r['supplier_name']) ?></td><td><?= \Hls\Http\View::money($r['total_amount']) ?></td><td><?= V::escape($r['status']) ?></td><td><a href="<?= $this->url('/finance/payable-detail?id='.(int)$r['id']) ?>">Detail</a><?php if($r['status']==='DRAFT'&&$access->can('finance.payable.create')): ?> <a href="<?= $this->url('/finance/payable-edit?id='.(int)$r['id']) ?>">Edit</a><?php endif ?></td></tr><?php endforeach ?></tbody></table><?php if(!$rows): ?><p class="empty-state">Belum ada tagihan supplier.</p><?php endif ?></div></section>